MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T USING (SELECT 'PlantSitebyEndCustomer' AS SQL_ID, 'DM' AS MDU_DIVS_CD, '[C] AS-IS @Code=''PlantSitebyEndCustomer'' 수작업 통합 변환 — auth-ext 제거 + 빈 파라미' AS SQL_NM, 'SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME FROM SCM_MGR.SCM_MST_SITE A WHERE A.SITE_TYPE = ''PLANT'' AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0) AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0) ORDER BY CODE' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'minyonglee1' AS CREATED_BY, TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'minyonglee1' AS LAST_UPDATED_BY, TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) S ON (T.SQL_ID=S.SQL_ID AND T.MDU_DIVS_CD=S.MDU_DIVS_CD)
